/*
 * Derived panel tables (docs/design.md, "Panel tables"). Built-in panels are generated by
 * tools/panelgen; grey panels can also be built at runtime
 * (epi_grey_panel_init).
 *
 * Fixed-point formats (Qn = n fractional bits). Every conversion from real
 * values rounds half away from zero (epi_round_shift, src/epi_math.h).
 */
#ifndef EPI_PANEL_TABLES_H
#define EPI_PANEL_TABLES_H

#include "epaper_image.h"

#include <stdint.h>

#define EPI_MAX_INKS 16
#define EPI_MAX_HULL_FACES 32
#define EPI_MAX_KERNEL_RADIUS 32

enum {
    EPI_PANEL_COLOUR = 0,
    EPI_PANEL_GREY = 1,
};

/* What both kinds read, and the first member of epi_colour_tables_t and
 * epi_grey_tables_t: epi_panel_t.tables points at it. */
struct epi_panel_tables {
    uint8_t kind; /* EPI_PANEL_COLOUR or EPI_PANEL_GREY */
    uint8_t ink_count;

    /* Detail kernel: taps -r..r, Q15, symmetric, sum exactly 32768. */
    uint8_t kernel_radius;
    uint16_t kernel[2 * EPI_MAX_KERNEL_RADIUS + 1];
};

/* Colour panels. XYZ is relative to source white Y = 1. */
typedef struct {
    epi_panel_tables_t base;
    int32_t white_xyz[3];             /* Q16: white ink, also the CIELAB reference white */
    int32_t black_xyz[3];             /* Q16: black ink (B_ink) */
    int32_t lin_to_panel_adapt[3][3]; /* Q16: diag(k)·A·M_srgb (the D = 1 part of the panel model) */
    int32_t lin_to_panel_bpc[3][3];   /* Q16: (W_y − B_y)·M_srgb (the D = 0 part of the panel model) */
    int32_t xyz_to_lin[3][3];         /* Q16: inverse of the 4-decimal sRGB matrix */
    int32_t lin_to_lms[3][3];         /* Q16: OK_M1·diag(1/white_lin) */
    int32_t lms_to_oklab[3][3];       /* Q16: OK_M2 */
    uint8_t hull_face_count;
    int32_t hull_n[EPI_MAX_HULL_FACES][3]; /* Q16 unit outward normal */
    int64_t hull_d[EPI_MAX_HULL_FACES];    /* Q32: inside iff n·xyz(Q16) + d <= 0 */
    int32_t lstar_min, lstar_max;          /* Q8: neutral interval of the hull */
    uint16_t cusp_lstar[360];              /* Q8: cusp L* at each integer hue degree */
    int32_t ink_lin[EPI_MAX_INKS][3];      /* Q16: measured inks, linear sRGB */
    int32_t ink_oklab[EPI_MAX_INKS][3];    /* Q16: measured inks, ink-relative OKLab */
    int32_t nhat[3];                       /* Q16: white_lin / |white_lin| */
} epi_colour_tables_t;

/* Grey panels (built by epi_grey_panel_init, src/epi_grey_panel.c). */
typedef struct {
    epi_panel_tables_t base;
    int32_t level_y[EPI_MAX_INKS]; /* Q16: level Y relative to the lightest level (last = 65536) */
    /* Q16 decision thresholds between levels i and i + 1:
     * floor(((cbrt(y_i) + cbrt(y_{i+1}))/2)^3 · 2^16), y = level_y/2^16. For
     * an integer working value v (Q16), v <= level_thr[i] iff cbrt(v) is at
     * least as close to cbrt(y_i) as to cbrt(y_{i+1}) (cbrt is monotone, and
     * flooring the threshold makes the test exact for integers, ties going
     * to the darker level). */
    int32_t level_thr[EPI_MAX_INKS - 1];
} epi_grey_tables_t;

/* The tables of a panel known to be of that kind. A pointer to a struct and
 * to its first member convert to each other (C11 6.7.2.1), but only to the
 * right kind: the colour struct is more strictly aligned and larger than a
 * grey object. */
static inline const epi_colour_tables_t* epi_colour_tables(const epi_panel_tables_t* t) {
    return (const epi_colour_tables_t*)t;
}

static inline const epi_grey_tables_t* epi_grey_tables(const epi_panel_tables_t* t) {
    return (const epi_grey_tables_t*)t;
}

/* Every grey panel's presets, runtime or generated (src/epi_grey_panel.c):
 * the colour presets without Vivid, because vibrance has no effect on grey. */
#define EPI_GREY_PRESET_COUNT 3
extern const epi_preset_t epi_grey_presets[EPI_GREY_PRESET_COUNT];

#endif /* EPI_PANEL_TABLES_H */
